set(3,'communityPrizeRoom','partial','lib/NativePrizeWalls.lua; lib/PrizeRoom.lua; lib/Gen3Scene.lua','Exact shared authored Prize Room wall panels and palette fit reviewed native Celadon blocked wall strips; source tile patterns, solid cells and adjacent floor must agree. Native clerks, counter, floors, exits and original OFF art are retained. Remaining authored furnishings, enclosure and ceiling are not adapted.')
set(3,'communityCourtyards','partial','lib/LegendaryFenceKit.lua; lib/NativeLegendaryFence.lua; lib/Gen3Outdoor.lua','Shared Gen1 authored posts, beveled caps, metal collars and double-rail bays consume native reviewed fence direction/endpoints and original material samples. Each replacement stays inside a blocked source cell; OFF restores native models. Authored courtyard paving and special landscape fixtures remain incomplete.')
set(3,'communityCasino','partial','lib/NativeLegendaryBuildings.lua; lib/CityArchitecture.lua; lib/CasinoFacade.lua; lib/Gen3Scene.lua','Shared authored Celadon casino and prize-annex models use exact native drawing patterns, warp-owned doors and blocked-body guards. Original OFF artwork remains; native door animation projects ahead of carved relief. Native casino interiors and other casino families are not yet adapted.')
set(3,'communityTrees','partial','lib/CommunityFlora.lua; lib/NativeLegendaryTrees.lua; lib/Gen3Scene.lua','Actual shared Gen1 mature bark/canopy/detail geometry is instanced and fitted to blocked path-edge footprints. Dedicated forest/Safari options retain ownership and OFF restores native models. Full wind behavior remains incomplete; explicit forest-only boundary scenery shares the same models. All five native Gen3 editions have isolated 0.3.85 ON/OFF runtime checks; Emerald Oldale and loaded neighbors additionally passed 750/750 eligible replacement placements without mixed fallback.')
function M.inventory(gen)
 local out={}
 for _,row in ipairs(V.require('SettingsCatalog'))do
  local state=assert(support[gen] and support[gen][row.key],'unknown option support')
  out[#out+1]={key=row.key,label=row.label,module=row.module,generation=gen,
   status=state.status,consumer=state.consumer,detail=state.detail,verification='source audit'}
 end
 return out
end
function M.rows(schema,gen)
 local out,seen={},{}
 for _,row in ipairs(schema)do out[#out+1]=row;seen[row.key]=true end
 for _,row in ipairs(M.inventory(gen))do
  if not seen[row.key] and row.key=='tiltshift' and gen<3 then
   out[#out+1]={key=row.key,label=row.label,pipeline='tiltshift'}
  elseif not seen[row.key] and row.status~='alias' then
   local labels={implemented='SUPPORTED',partial='PARTIAL',missing='UNAVAILABLE',
    not_applicable='OTHER ENGINE',provider='PROVIDER'}
   local label=row.key=='tiltshift' and gen<3 and 'PIPELINE' or labels[row.status]
   out[#out+1]={key=row.key,label=row.label,type='choice',readOnly=true,
    supportOnly=true,unavailable=label,help=row.detail}
  end
 end
 return out
end
return M
